#include <iostream>
int main(){int n;std::cout<<"Enter array size (1-100): ";if(!(std::cin>>n)||n<1||n>100){std::cout<<"Array size must be from 1 to 100.\n";return 0;}int a[100];for(int i=0;i<n;++i)if(!(std::cin>>a[i])){std::cout<<"Enter array values and one target.\n";return 0;}int target;if(!(std::cin>>target)){std::cout<<"Enter one target whole number.\n";return 0;}if(std::cin>>std::ws&&std::cin.peek()!=std::char_traits<char>::eof()){std::cout<<"Enter only the array values and target.\n";return 0;}int found=-1;for(int i=0;i<n;++i)if(a[i]==target){found=i;break;}if(found<0)std::cout<<"Not found\n";else std::cout<<"Found at index "<<found<<'\n';}
